# Homebrew formula for RemoHop, generated by scripts/gen-manifests.sh from a release.
# Tap layout: the repository readori/homebrew-tap, with this file at Formula/remohop.rb
# (and the quick-support cask at Casks/remohop-quick.rb). Then:
#   brew install readori/tap/remohop
# Until the release assets are public, brew cannot download them (no credentials).
class Remohop < Formula
  desc "Lightweight peer-to-peer remote control over an end-to-end encrypted session"
  homepage "https://github.com/readori/RemoHop"
  version "1.0.0"
  license "AGPL-3.0-only"

  # The macOS binary is one universal (arm64 + x86_64), Developer ID signed and
  # notarized executable. Homebrew must not modify it (that would void the signature).
  on_macos do
    url "https://github.com/readori/RemoHop/releases/download/v1.0.0/remohop_darwin_universal.tar.gz"
    sha256 "f9c3d301307df8d40078b462430fee85be907becb4aa0dc90678b81eae62d456"
  end

  on_linux do
    on_intel do
      url "https://github.com/readori/RemoHop/releases/download/v1.0.0/remohop_linux_amd64.tar.gz"
      sha256 "409f68c6da45226f7bbcf818a755a99fd301f0c5ba1a8a77b066b88eb500ccf7"
    end
    on_arm do
      url "https://github.com/readori/RemoHop/releases/download/v1.0.0/remohop_linux_arm64.tar.gz"
      sha256 "4d7e992121f235c14d8e3aa03824c33005834adf37f363ed7b7692f994c1861a"
    end
  end

  def install
    bin.install "remohop"
    doc.install "LICENSE", "NOTICE", "THIRD_PARTY_LICENSES.txt"
  end

  def caveats
    <<~EOS
      Nothing runs until you start it. To host this machine:
        remohop host
      or, to start it at login:
        remohop service install
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/remohop version")
  end
end
